// GENERATED by make_model_ref.py from model.js -- do not edit.
// Identical to model.js except that every parameter, plus
// --maxtime/--size/--outdir, can be set from the command line.
Simulation = require('./cacatoo.js') // Loads the Simulation class from installation, or from local package like below
const yargs = require('yargs')

// Parse arguments
const cmd_params = yargs.argv

// Parameters

iter = cmd_params.seed
mixinp = (cmd_params.mixinp !== undefined ? cmd_params.mixinp : 0)
alpha = (cmd_params.alpha !== undefined ? cmd_params.alpha : 0.5) // initial alpha value

b = (cmd_params.b !== undefined ? cmd_params.b : 0.05)      // maximum host birth probability
cI = (cmd_params.cI !== undefined ? cmd_params.cI : 0.0)     // fractional decrease in birth probability per provirus
d = (cmd_params.d !== undefined ? cmd_params.d : 0.01)      // host death probability
beta = (cmd_params.beta !== undefined ? cmd_params.beta : 0.5)    // virus entry probability
lambda = cmd_params.lambda  // integration probability  //0.1 and 0.01
scheme = cmd_params.scheme  // scheme = 1 ; integration independent of MOI
                                    //= 2 ; integration less likely for high MOI
                                    //= 3 ; integration more likley for high MOI

r = (cmd_params.r !== undefined ? cmd_params.r : 0.25)       // virus maximum replication probability
c_alpha = (cmd_params.c_alpha !== undefined ? cmd_params.c_alpha : 0.5)  // cost of cooperation
e = cmd_params.e        // provirus excision probability
latency = (cmd_params.latency !== undefined ? cmd_params.latency : 20)   // virus replication latency period

muA = (cmd_params.muA !== undefined ? cmd_params.muA : 0.001)    // mutation probability during virus replication
step = (cmd_params.step !== undefined ? cmd_params.step : 0.1)     // Standard deviation of mutation
loss = (cmd_params.loss !== undefined ? cmd_params.loss : 0.001)   // probability of provirus loss during host reproduction

diff_rate = (cmd_params.diff_rate !== undefined ? cmd_params.diff_rate : 0.5)   // extracellular virus diffusion probability
decay_rate = (cmd_params.decay_rate !== undefined ? cmd_params.decay_rate : 0.2)  // extracellular virus decay probability

var size = (cmd_params.size !== undefined ? cmd_params.size : 200)
var outdir = (cmd_params.outdir !== undefined ? cmd_params.outdir : 'sweep_11aug26')

////// DEFINE FUNCTIONS ///////////////////////////////////////////////////////////

function gaussianRandom() {
  // Draw a random number from a Gaussian distribution; mean 0, std dev 1
  let u1 = sim.rng.genrand_real1();
  let u2 = sim.rng.genrand_real1();

  u1 = Math.max(u1, Number.EPSILON);

  return Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
}

function gaussianStep(A, D, min, max) {
  // Gaussian mutation step with truncation
  let step = D * gaussianRandom();
  let newA = A + step;

  return Math.min(max, Math.max(min, newA));
}

function histogramInt(values) {
  // Histogram of integer values 0 to 100
  var bins = new Array(100).fill(0);

  for (let i = 0; i < values.length; i++) {
    if (values[i] < 100) bins[values[i]]++;
    else bins[99]++;
  }

  return bins;
}

function histogram(A, binSize = 0.01) {
  // Histogram of numbers between 0 and 1 with bin size 0.01
  const nBins = Math.round(1 / binSize);

  var bins = new Array(nBins).fill(0);

  for (let i = 0; i < A.length; i++) {
    let x = A[i];

    if (x < 0 || x > 1) continue;

    let ix = Math.floor(x / binSize);

    // handle edge case where value === 1
    if (ix === nBins) ix = nBins - 1;

    bins[ix]++;
  }

  return bins;
}

////////// CONFIGURATION ////////////////////////////////////////////////////

let config = {
  title: "Virus factory model",
  description: "Individual based model of hyperparasitism evolution",
  maxtime: (cmd_params.maxtime !== undefined ? cmd_params.maxtime : 200000),
  seed: iter,
  ncol: size,
  nrow: size,
  wrap: [true, true]
}

sim = new Simulation(config)

//// check mixedness of simulation
if (mixinp == 1) sim.mixhosts = true
else sim.mixhosts = false

sim.makeGridmodel("host")
sim.makeGridmodel("ext")

// VIRUS object
class Virus {

  constructor(init_alpha) {
    this.alpha = init_alpha
  }

  copy(mutate) {
    let child = new Virus()
    child.alpha = this.alpha
    if (mutate) {
      var randomnr = sim.rng.genrand_real1()
      if (randomnr < muA) child.alpha = gaussianStep(this.alpha, step, 0, 1)
    }
    return child
  }
}

// Function for extracellular virus dynamics
sim.ext.diffuse_particles = function(x, y, diff_rate, decay_rate, mix) {
  var remove_list = []
  for (let k = 0; k < this.grid[x][y].viruses.length; k++) {
    if (sim.rng.genrand_real1() < decay_rate){
      remove_list.push(k)
    }
    else {
      if (diff_rate > 1 || mix) {
        var p = sim.rng.genrand_int(0,this.nc-1)
        var q = sim.rng.genrand_int(0,this.nr-1)
        nbr = this.grid[p][q]
        nbr.viruses.push(this.grid[x][y].viruses[k])
        remove_list.push(k)
      }
      else if (sim.rng.genrand_real1() < diff_rate){
        nbr = this.randomMoore8(this, x, y)
        nbr.viruses.push(this.grid[x][y].viruses[k])
        remove_list.push(k)
      }
    }
  }
  var remove_list = new Set(remove_list)
  this.grid[x][y].viruses = this.grid[x][y].viruses.filter((_, k) => !remove_list.has(k))
  this.grid[x][y].density = this.grid[x][y].viruses.length
}

//////// INITIALISATION ////////////////////////////////////////////////////////////////
sim.initialGrid(sim.host, "alive", 'empty', "S", 1.0)
for (let i = 0; i < sim.host.nc; i++) for (let j = 0; j < sim.host.nr; j++){
  sim.host.grid[i][j].provirus = []
  if (sim.rng.genrand_real1()<0.5) sim.host.grid[i][j].provirus.push(new Virus(alpha))
  sim.host.grid[i][j].factory = []
  sim.host.grid[i][j].NP = 0
}

//Insert virus at every grid point w.p. 0.01
sim.initialGrid(sim.host, "clock", 0)
for (let i = 0; i < sim.ext.nc; i++) for (let j = 0; j < sim.ext.nr; j++) {
  sim.ext.grid[i][j].viruses = []
  if (sim.rng.genrand_real1() < 0.01) sim.ext.grid[i][j].viruses.push(new Virus(alpha))
}

//////// NEXT STATE FUNCTION ////////////////////////////////////////////////////////////
sim.host.nextState = function (i, j) {

  // If host is susceptible
  if (this.grid[i][j].alive == "S") {

    // Die with probability d
    var rand = sim.rng.genrand_real1()
    if (rand < d) {
      this.grid[i][j].alive = 'empty'
      this.grid[i][j].provirus = undefined
      this.grid[i][j].factory = undefined
      this.grid[i][j].clock = undefined
      this.grid[i][j].NP = undefined
    }

    else {

      // Pick viruses to infect
      var remove_list = []
      var infection = []
      for (let v = 0; v < sim.ext.grid[i][j].viruses.length; v++) {
        if (sim.rng.genrand_real1() < beta){
          infection.push(sim.ext.grid[i][j].viruses[v].copy(false))
          remove_list.push(v)
        }
      }
      var remove_list = new Set(remove_list)
      sim.ext.grid[i][j].viruses = sim.ext.grid[i][j].viruses.filter((_, k) => !remove_list.has(k)) // remove picked viruses from the environment
      sim.ext.grid[i][j].density = sim.ext.grid[i][j].viruses.length

      // check if picked viruses can set up a virus factory
      // if true, move all picked viruses to the factory and start clock
      if (infection.length > 0) {
        if (scheme == 1) { // chance of integration independent of MOI
          if (sim.rng.genrand_real1() > lambda) {
            this.grid[i][j].alive = 'I'
            for (let v = 0; v < infection.length; v++) this.grid[i][j].factory.push(infection[v].copy(false))
            this.grid[i][j].clock = 1
          }
          else {
            for (let v = 0; v < infection.length; v++) {
              this.grid[i][j].provirus.push(infection[v].copy(false))
              this.grid[i][j].NP ++
            }
          }
        }
        else if (scheme == 2) { // chance of integration decreases with MOI
          if (sim.rng.genrand_real1() < 0.2*infection.length) {
            this.grid[i][j].alive = 'I'
            for (let v = 0; v < infection.length; v++) this.grid[i][j].factory.push(infection[v].copy(false))
            this.grid[i][j].clock = 1
          }
          else {
            for (let v = 0; v < infection.length; v++) {
              this.grid[i][j].provirus.push(infection[v].copy(false))
              this.grid[i][j].NP ++
            }
          }
        }
        else if (scheme == 3) { // chance of integration increases with MOI
          if (sim.rng.genrand_real1() > 0.2*infection.length) {
            this.grid[i][j].alive = 'I'
            for (let v = 0; v < infection.length; v++) this.grid[i][j].factory.push(infection[v].copy(false))
            this.grid[i][j].clock = 1
          }
          else {
            for (let v = 0; v < infection.length; v++) {
              this.grid[i][j].provirus.push(infection[v].copy(false))
              this.grid[i][j].NP ++
            }
          }
        }
      }
    }
  }

  // If host already has a factory
  else if (this.grid[i][j].alive == "I") {

    // check if provirus joins factory
    for (let v = this.grid[i][j].provirus.length-1; v >= 0; v--) {
      var rand = sim.rng.genrand_real1()
      if (rand < e) {
        this.grid[i][j].factory.push(this.grid[i][j].provirus[v].copy(false))
        this.grid[i][j].provirus.splice(v, 1)
        this.grid[i][j].NP --
      }
    }

    // virus replication
    this.grid[i][j].alphaAvg = 0
    for (let v = 0; v < this.grid[i][j].factory.length; v++) this.grid[i][j].alphaAvg += this.grid[i][j].factory[v].alpha
    this.grid[i][j].alphaAvg = this.grid[i][j].alphaAvg / this.grid[i][j].factory.length

    this.grid[i][j].offspring = []
    for (let v = 0; v < this.grid[i][j].factory.length; v++) {
      if (sim.rng.genrand_real1() < r*this.grid[i][j].alphaAvg*(1-c_alpha*this.grid[i][j].factory[v].alpha)) this.grid[i][j].offspring.push(this.grid[i][j].factory[v].copy(true))
    }

    for (let v = 0; v < this.grid[i][j].offspring.length; v++) this.grid[i][j].factory.push(this.grid[i][j].offspring[v].copy(false))

    this.grid[i][j].clock ++

    if (this.grid[i][j].clock == latency) {
      for (let v = 0; v < this.grid[i][j].factory.length; v++) sim.ext.grid[i][j].viruses.push(this.grid[i][j].factory[v].copy(false))
      this.grid[i][j].alive = 'empty'
      this.grid[i][j].provirus = undefined
      this.grid[i][j].factory = undefined
      this.grid[i][j].clock = undefined
      this.grid[i][j].NP = undefined
    }

  }


  else {

    // host reproduction into empty grid point
    var nbr = this.randomMoore8(this, i, j)
    if (nbr.alive == 'S') {
      if (sim.rng.genrand_real1() < b*(1-cI*nbr.provirus.length)) {
        this.grid[i][j].alive = 'S'
        this.grid[i][j].provirus = []
        this.grid[i][j].factory = []
        this.grid[i][j].clock = 0
        for (let v = 0; v < nbr.provirus.length; v++) {
          // lose provirus with probability
          if (sim.rng.genrand_real1() >= loss) this.grid[i][j].provirus.push(nbr.provirus[v].copy(true))
        }
        this.grid[i][j].NP = this.grid[i][j].provirus.length
      }
    }
  }

}

sim.ext.nextState = function(i, j) {
  this.diffuse_particles(i, j, diff_rate, decay_rate, sim.mixhosts)
}

sim.host.update = function() {
  if(sim.mixhosts) sim.host.perfectMix()
  this.synchronous()

  if (sim.time%100==0) {
    var provirus_alpha = []
    var virion_alpha = []
    var num_provirus = []
    var num_S = 0
    var num_I = 0
    for (let i = 0; i < sim.host.nc; i++) for (let j = 0; j < sim.host.nr; j++){
      if (this.grid[i][j].alive == 'S') {
        num_S++
        for (let v = 0; v < this.grid[i][j].provirus.length; v++) {
          provirus_alpha.push(this.grid[i][j].provirus[v].alpha)
        }
        num_provirus.push(this.grid[i][j].provirus.length)
      }
      else if (this.grid[i][j].alive == 'I') {
        num_I++
        for (let v = 0; v < this.grid[i][j].factory.length; v++) {
          virion_alpha.push(this.grid[i][j].factory[v].alpha)
        }
      }
      for (let v = 0; v < sim.ext.grid[i][j].viruses.length; v++) {
        virion_alpha.push(sim.ext.grid[i][j].viruses[v].alpha)
      }
    }

    var P = histogram(provirus_alpha)
    var V = histogram(virion_alpha)
    var PN = histogramInt(num_provirus)

    if (scheme == 1) filename = outdir+'/scheme1_lambda'+lambda+'_ex'+e+'_seed'+iter+'.txt'
    else filename = outdir+'/scheme'+scheme+'_ex'+e+'_seed'+iter+'.txt'

    sim.write_append(JSON.stringify({time: sim.time, num_S: num_S, num_I: num_I, provirus: P, virion: V, num_provirus: PN}) + '\n', filename)
    if (virion_alpha.length == 0) sim.stop()
  }
}

sim.ext.update = function() {
  this.asynchronous()
}

sim.start()
